import csv
import io


def parse_csv(raw_csv: str):
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",",
                         quotechar='"', doublequote=True)

    def normalize(record):
        if len(record) < 3:
            return record + [""] * (3 - len(record))
        if len(record) > 3:
            # Recover unquoted commas in the merchant name without dropping fields.
            return [record[0], ",".join(record[1:-1]), record[-1]]
        return record

    header = next(records, None)
    if header is None:
        return {"columns": [], "rows": []}

    return {
        "columns": normalize(header),
        "rows": [normalize(record) for record in records],
    }
